// Settings from the Household page (Infra section) -> global.infra_config (21-10-2026).
// Missing/invalid -> today's defaults; a broken cross rule -> all five defaults.
const SC = global.get('infra_config') || {};
const cfgNum = (k, d, lo, hi, st) => { const v = Number(SC[k]); return (SC[k] !== undefined && SC[k] !== '' && SC[k] !== null && isFinite(v) && v >= lo && v <= hi && Math.abs(v / st - Math.round(v / st)) < 1e-9) ? v : d; };
var G_S = cfgNum('grace_secs', 90, 30, 600, 1), T2_M = cfgNum('escalate_mins', 10, 2, 60, 1), T3_M = cfgNum('repeat_core_mins', 15, 5, 120, 1), T3S_M = cfgNum('repeat_other_mins', 60, 5, 240, 1), MULTI_N = cfgNum('multi_down', 3, 2, 20, 1);
if (!(G_S < T2_M * 60 && T3_M <= T3S_M)) { G_S = 90; T2_M = 10; T3_M = 15; T3S_M = 60; MULTI_N = 3; }
const GRACE=G_S*1000, T2=T2_M*60*1000, T3=T3_M*60*1000, T3_SLOW=T3S_M*60*1000, MULTI=MULTI_N;
const GRACE_TXT=(G_S<120)?(G_S+'s'):(Math.round(G_S/60)+'m');   // first-push wording, e.g. ~90s
const CORE={'Home Assistant':1,'MQTT broker':1,'Pi-hole primary':1,'proxmox1':1,'proxmox2':1,'proxmox-remote':1,'TrueNAS':1,'MikroTik RB5009 (gateway)':1};
function dub(){return new Date().toLocaleString('en-IE',{timeZone:'Europe/Dublin',hour12:false});}
function dhour(){return parseInt(new Date().toLocaleString('en-IE',{timeZone:'Europe/Dublin',hour:'2-digit',hour12:false}),10);}
// Quiet hours shared by both infra flows: Household page -> Infra (global.infra_config). Default 22:00-07:00.
function quiet(){var IC=global.get('infra_config')||{};var okT=function(s){return typeof s==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(s);};var qs=okT(IC.quiet_start)?IC.quiet_start:'22:00', qe=okT(IC.quiet_end)?IC.quiet_end:'07:00';if(qs===qe){qs='22:00';qe='07:00';}var m=function(s){return Number(s.slice(0,2))*60+Number(s.slice(3,5));};var d=new Date();var n=parseInt(d.toLocaleString('en-IE',{timeZone:'Europe/Dublin',hour:'2-digit',hour12:false}),10)*60+parseInt(d.toLocaleString('en-IE',{timeZone:'Europe/Dublin',minute:'2-digit'}),10);var a=m(qs),b=m(qe);return a<b?(n>=a&&n<b):(n>=a||n<b);}
function hhmm(ts){return new Date(ts).toLocaleTimeString('en-IE',{timeZone:'Europe/Dublin',hour:'2-digit',minute:'2-digit'});}
function dur(ms){var m=Math.max(1,Math.round(ms/60000));if(m<60)return m+'m';return Math.floor(m/60)+'h'+(m%60)+'m';}
function durWords(ms){var m=Math.max(1,Math.round(ms/60000));var h=Math.floor(m/60),mm=m%60;var pp=[];if(h)pp.push(h+' hour'+(h>1?'s':''));if(mm||!h)pp.push(mm+' minute'+(mm===1?'':'s'));return pp.join(' and ');}
function phone(t,m,tag){if(global.get('maintenance_mode')){log('[maint-suppressed] '+t+' — '+m);return;}node.send([{title:t,message:m,ndata:{tag:tag||'infra',channel:'Infra'}},null,null]);}
function tts(m){if(global.get('maintenance_mode')){log('[maint-suppressed-tts] '+m);return;}node.send([null,{message:m},null]);}
function log(s){node.send([null,null,{payload:dub()+'  '+s+'\n'}]);}
function countDown(){return Object.keys(context.get('S','file')||{}).length;}
function clr(mon){var T=context.get('T')||{};var t=T[mon];if(t){if(t.grace)clearTimeout(t.grace);if(t.t2)clearTimeout(t.t2);if(t.t3)clearInterval(t.t3);delete T[mon];context.set('T',T);}}

// 24-08-2026: S (currently-down monitors) and ON (recovered-overnight events) moved
// to the file-backed context store so a Node-RED restart (e.g. mid-deploy) doesn't
// silently drop an in-progress outage or its eventual recovery notification. T (the
// live setTimeout/setInterval handles) stays in-memory -- those can't be serialised --
// and is re-armed on deploy by the 'reconcile-timers' branch below, which resumes each
// persisted monitor at its last known tier with the correctly REMAINING delay rather
// than re-arming from zero (so a restart never re-sends a notification that already
// went out, and never waits longer than it should have for the next one).
// core is read from S[mon].core inside the timer bodies (identical to the CORE lookup
// at detection time, since CORE is a static table) so the same arm* functions work
// whether called fresh or resumed.
function armGrace(mon, delay){
  return setTimeout(function(){
    var S=context.get('S','file')||{}; if(!S[mon])return;
    var core=S[mon].core;
    S[mon].tier=1; context.set('S',S,'file');
    if(quiet()){var ON=context.get('ON','file')||[];ON.push({type:'down',mon:mon,from:S[mon].downSince});context.set('ON',ON,'file');log('[quiet] '+mon+' down held');}
    else{phone((core?'🔴':'⚠️')+' '+mon+' is DOWN',mon+' down ~'+GRACE_TXT+' (since '+hhmm(S[mon].downSince)+').','infra_'+mon);log('[tier1] '+mon);}
  },delay);
}
function armT2(mon, delay){
  return setTimeout(function(){
    var S=context.get('S','file')||{}; if(!S[mon])return;
    var core=S[mon].core;
    S[mon].tier=2; context.set('S',S,'file');
    if(quiet())return;
    phone((core?'🔴':'⚠️')+' '+mon+' STILL DOWN',mon+' down '+dur(Date.now()-S[mon].downSince)+'.','infra_'+mon);
    tts('Attention. '+mon+' has been down for '+durWords(Date.now()-S[mon].downSince)+'.');
    log('[tier2] '+mon+' phone+tts');
    var T=context.get('T')||{};
    if(T[mon]&&!T[mon].t3){var iv=(core||countDown()>=MULTI)?T3:T3_SLOW;
      T[mon].t3=armT3(mon, iv);
      context.set('T',T);
    }
  },delay);
}
function t3Tick(mon){
  var S=context.get('S','file')||{}; if(!S[mon])return; if(quiet())return;
  phone('🔴 '+mon+' STILL DOWN',mon+' down '+dur(Date.now()-S[mon].downSince)+'.','infra_'+mon);
  tts(mon+' is still down after '+durWords(Date.now()-S[mon].downSince)+'.');
  log('[tier3] '+mon+' repeat');
}
function armT3(mon, iv){
  return setInterval(function(){ t3Tick(mon); },iv);
}
// Resumption-only: the fresh path's setInterval(iv) always ticks in step with
// downSince+T2, downSince+T2+iv, +2*iv, ... -- a plain setInterval(iv) armed at
// the restart moment would instead tick iv after the RESTART, drifting off that
// schedule. This fires once at the correctly phase-aligned remaining delay, then
// hands off to a normal setInterval(iv) for the rest, so later ticks land on the
// exact same absolute times an uninterrupted run would have used.
function armT3Resumed(mon, firstDelay, iv){
  return setTimeout(function(){
    t3Tick(mon);
    var T=context.get('T')||{};
    if(T[mon]){ T[mon].t3=armT3(mon, iv); context.set('T',T); }
  },firstDelay);
}

if(msg && msg.topic==='reconcile-timers'){
  var S=context.get('S','file')||{};
  var T=context.get('T')||{};
  var now=Date.now();
  var resumed=0;
  for(var rmon in S){
    if(T[rmon]) continue;   // already armed -- shouldn't happen right after a restart, but safe
    var rec=S[rmon];
    var elapsed=now-rec.downSince;
    T[rmon]={};
    if(rec.tier===0){
      T[rmon].grace=armGrace(rmon, Math.max(0,GRACE-elapsed));
      T[rmon].t2=armT2(rmon, Math.max(0,T2-elapsed));
    } else if(rec.tier===1){
      T[rmon].t2=armT2(rmon, Math.max(0,T2-elapsed));
    } else {
      var iv=(rec.core||countDown()>=MULTI)?T3:T3_SLOW;
      var sinceT2=elapsed-T2;                     // T2 always fires at exactly downSince+T2
      var phase=((sinceT2%iv)+iv)%iv;              // guard negative in case T2 hasn't strictly elapsed yet
      var firstDelay=(phase===0)?iv:(iv-phase);
      T[rmon].t3=armT3Resumed(rmon, firstDelay, iv);
    }
    context.set('T',T);
    resumed++;
    log('[restart-reconcile] resumed '+rmon+' at tier '+rec.tier+' (down '+dur(elapsed)+')');
  }
  if(!resumed) log('[restart-reconcile] nothing to resume');
  return null;
}

if(msg && msg.topic==='flush'){
  var S=context.get('S','file')||{}, ON=context.get('ON','file')||[], lines=[];
  for(var m in S){lines.push('• '+m+' still DOWN since '+hhmm(S[m].downSince));}
  ON.filter(function(e){return e.type==='recovered';}).forEach(function(e){lines.push('• '+e.mon+' was down '+hhmm(e.from)+'–'+hhmm(e.to)+' (recovered)');});
  if(lines.length){phone('🔧 Overnight infra summary',lines.join('\n'),'infra_summary');log('[7am] '+lines.length+' item(s)');}
  context.set('ON',[],'file');
  return null;
}

var p=msg.payload||{};
var mon=(p.monitor&&p.monitor.name)||p.name;
if(!mon) return null;
if((p.monitor&&p.monitor.type==='group')||({'Infra':1,'Services':1,'Network':1})[mon]) return null;
var st=(p.heartbeat&&p.heartbeat.status); if(st===undefined&&p.status!==undefined)st=p.status;
var core=!!CORE[mon];
var S=context.get('S','file')||{};

if(st===0||st==='0'){
  if(S[mon]) return null;
  S[mon]={downSince:Date.now(),tier:0,core:core}; context.set('S',S,'file');
  var T=context.get('T')||{}; T[mon]={}; context.set('T',T);
  log('[down-rcv] '+mon+(core?' (core)':''));
  T[mon].grace=armGrace(mon, GRACE);
  T[mon].t2=armT2(mon, T2);
  context.set('T',T);
}else if(st===1||st==='1'){
  if(!S[mon])return null;
  var ds=S[mon].downSince, tier=S[mon].tier;
  clr(mon); delete S[mon]; context.set('S',S,'file');
  if(quiet()){var ON=context.get('ON','file')||[];ON.push({type:'recovered',mon:mon,from:ds,to:Date.now()});context.set('ON',ON,'file');log('[quiet] '+mon+' recovered');}
  else if(tier>=1){phone('✅ '+mon+' recovered',mon+' back up after '+dur(Date.now()-ds)+'.','infra_'+mon);if(tier>=2)tts(mon+' is back online, after '+durWords(Date.now()-ds)+' down.');log('[recovered] '+mon+(tier>=2?' (+tts)':''));}
  else{log('[up] '+mon+' (within grace)');}
}
return null;

var p=msg.payload||{};
var ns=p.new_state&&p.new_state.state, os=p.old_state&&p.old_state.state;
if(ns!=='off'||os!=='on')return null;
msg.reconSrc='maint-off';msg.reconAttempt=1;
return msg;

var map={};
((msg.payload&&msg.payload.publicGroupList)||[]).forEach(function(g){(g.monitorList||[]).forEach(function(m){map[m.id]=m.name;});});
msg.idmap=map;
delete msg.payload;delete msg.headers;
return msg;

var idmap=msg.idmap||{};
var hb=(msg.payload&&msg.payload.heartbeatList)||{};
var src=msg.reconSrc||'maint-off';
var out=[],maint=0,seen=0;
for(var id in hb){
  var b=hb[id];
  if(!b||b.length<3)continue;
  if(!idmap[id])continue;
  seen++;
  if(b[b.length-1].status===3)maint++;
  var tail=b.slice(-3);
  var allUp=tail.every(function(x){return x&&x.status===1;});
  if(allUp){out.push({payload:{heartbeat:{status:1,msg:src+' reconcile'},monitor:{name:idmap[id]}}});}
}
if(src==='periodic'){return [out,null,null];}
var att=msg.reconAttempt||1;
var retry=(maint>0&&att<10)?{reconSrc:'maint-off',reconAttempt:att+1}:null;
var ts=new Date().toLocaleString('en-IE',{timeZone:'Europe/Dublin',hour12:false});
var line=ts+'  [maint-off-reconcile] attempt '+att+' injected '+out.length+' up-events ('+maint+'/'+seen+' still in maintenance'+(retry?', retry in 30s':'')+')\n';
return [out,[{payload:line}],retry?[retry]:null];

const PC = global.get('person_config') || {};
const ents = msg.payload || [];
const S = id => { const e = ents.find(x => x.entity_id === id); return e && e.state; };
const anyoneHome = Object.keys(PC).some(function(pid){
  var c = PC[pid];
  return c && c.infra_alerts && S(pid) === 'home';
});
if (!anyoneHome) return null;
return msg;

// 60 s tick -> passes ONCE per day, in the 5 minutes after the end of the shared infra quiet
// hours (Household page -> Infra, default 07:00), carrying the inject's topic 'flush' (infra watchdog).
const IC = global.get('infra_config') || {};
const okT = s => typeof s === 'string' && /^([01]\d|2[0-3]):[0-5]\d$/.test(s);
let QS = okT(IC.quiet_start) ? IC.quiet_start : '22:00', QE = okT(IC.quiet_end) ? IC.quiet_end : '07:00';
if (QS === QE) { QS = '22:00'; QE = '07:00'; }
const T = Number(QE.slice(0, 2)) * 60 + Number(QE.slice(3, 5));
const d = new Date();
const since = ((d.getHours() * 60 + d.getMinutes()) - T + 1440) % 1440;
if (since >= 5) return null;
const day = new Date(d.getTime() - since * 60000).toDateString();
if (context.get('lastDay') === day) return null;
context.set('lastDay', day);
node.warn('[gate] infra watchdog flush (' + QE + ')');
return msg;
